	// function l is executed at tier s and l2 at tier s+k
	MP_variable z(P,AST2,E,T);
	z.setName("z");	
	z.upperLimit(P,AST2,E,T)=us2(AST2,P);
	z.upperLimit(P,AST2,0,T)=0;
	z.upperLimit(P,AST2,numOfPeriods+1,T)=0;
