	MP_variable x(FTP,F,L,E,T); //1F23
	x.upperLimit(FTP,F,L,0,T)=0;
	x.upperLimit(FTP,4,L,0,T)=0;
	x.upperLimit(FTP,5,L,0,T)=0;

	x.upperLimit(FTP,F,L,numOfPeriods+2,T)=0;
	x.upperLimit(FTP,F,L,numOfPeriods+1,T)=0;
	x.setName("x");	

	MP_variable x1(FTP,F,L,E); //Ffactory
	x1.upperLimit(FTP,F,L,0)=0;
	x1.upperLimit(FTP,2,L,0)=0;
	x1.upperLimit(FTP,3,L,0)=0;
	x1.upperLimit(FTP,4,L,0)=0;
	x1.upperLimit(FTP,5,L,0)=0;
	x1.upperLimit(FTP,F,L,numOfPeriods+2)=0;
	x1.upperLimit(FTP,F,L,numOfPeriods+1)=0;
	x1.setName("x1");	

	//TL(P,L)
	MP_variable v(P,F,E,T); //F23
	v.setName("v");
	v.upperLimit(P,4,E,T)=0;
	v.upperLimit(P,5,E,T)=0;

