	MP_constraint facility_capacity_stage1(P,F,L,E);

	facility_capacity_stage1(P,F,L,E+1).such_that(Ffactory(F))=

		sum(P2(pi2).such_that(TF(L,P,pi2)), x1(FTP(P,pi2),F,L,E))

		<=

		ut(P,L,F)* y(F,L);

	facility_capacity_stage1.setName("facility_capacity_stage1");


//Facility capacity Stage 2
	MP_constraint facility_capacity_stage(P,F,L,E);
		facility_capacity_stage(P,F,L,E+1).such_that(F23(F)) =


		sum(P2(pi2).such_that(TF(L,P,pi2)), x(FTP(P,pi2),F,L,E,1))
		<=
		ut(P,L,F)* y(F,L);

	facility_capacity_stage.setName("facility_capacity_stage");

