		+ sum(L(li)*P2.such_that(TF(li,P2,P)), x1(FTP(P2,P),F,li,E))

		>=

		v1(P,F,E) + sum(AST1(F,arcj),z1(P,AST1(F,arcj),E)) 
		
		+  sum(L(li).such_that(TL(P,li))*P2.such_that(TF(li,P,P2)), x1(FTP(P,P2),F,li,E)) ;


	balancing_Stage1.setName("balancing_stage1");


	MP_constraint balancing2Stage1(P,F,E);

	balancing2Stage1(P,F,E+1).such_that(Ffactory(F))=

		v1(P,F,E-1) 
		
		+ sum(L(li)*P2.such_that(TF(li,P2,P)), x1(FTP(P2,P),F,li,E))

		<=

		v1(P,F,E) + sum(AST1(F,arcj),z1(P,AST1(F,arcj),E)) 
		
		+  sum(L(li).such_that(TL(P,li))*P2.such_that(TF(li,P,P2)), x1(FTP(P,P2),F,li,E)) ;


	balancing2Stage1.setName("balancingStage1_2");


//Stage 2 /////////////////////////////////////////
	MP_constraint balancing(P,F,E,T);

	balancing(P,F,E+1,T+1).such_that(F23(F))=

		sup(E,F,P) + v(P,F,E-1,T) + sum(AST1(arci,F),z1(P,AST1(arci,F),E-dur1(AST1(arci,F))))
		
		+ sum(AST2(arci2,F),z(P,AST2(arci2,F),E-dur2(AST2(arci2,F)),T))
		
		+ sum(L(li)*P2.such_that(TF(li,P2,P)), x(FTP(P2,P),F,li,E,T))

		>=

		v(P,F,E,T) + sum(AST2(F,arcj2),z(P,AST2(F,arcj2),E,T)) 
		
		+  sum(L(li).such_that(TL(P,li))*P2.such_that(TF(li,P,P2)), x(FTP(P,P2),F,li,E,T)) ;


	balancing.setName("balancing");


	MP_constraint balancing2(P,F,E,T);

	balancing2(P,F,E+1,T+1).such_that(F23(F))=

		v(P,F,E-1,T) + sum(AST1(arci,F),z1(P,AST1(arci,F),E-dur1(AST1(arci,F))))

		+ sum(AST2(arci2,F),z(P,AST2(arci2,F),E-dur2(AST2(arci2,F)),T))
		
		+ sum(L(li)*P2.such_that(TF(li,P2,P)), x(FTP(P2,P),F,li,E,T))

		<=

		v(P,F,E,T) + sum(AST2(F,arcj2),z(P,AST2(F,arcj2),E,T)) 
		
		+  sum(L(li).such_that(TL(P,li))*P2.such_that(TF(li,P,P2)), x(FTP(P,P2),F,li,E,T)) ;


	balancing2.setName("balancing2");

