void writeSolutionInfoDetEq(OsiSolverInterface *osiSolver, const char *name, const double &duration) {
	string filename = name;
	filename = filename.append(".txt");
	ofstream ofs;
	ofs.open(filename.c_str(), std::ios::app);
	ofs << "Obj. Value: " << osiSolver->getObjValue() << endl;
	ofs << "Duration (secs): " << duration << endl;
	ofs << "-------------------------" << endl;
	ofs.close();
}

void solveDetEquivalentFromSMPS(const char *name) {

	SmiScnModel* smiModel = new SmiScnModel();
	OsiCpxSolverInterface c1;
	smiModel->setOsiSolverHandle(c1);
	smiModel->readSmps(name,SmiCoreCombineReplace::Instance());

	//// solve the det. equivalent
	OsiSolverInterface *osiStoch = smiModel->loadOsiSolverData();
	osiStoch->setObjSense(MP_model::MINIMIZE);
	double begin = CoinCpuTime();
	osiStoch->branchAndBound();
	double duration = CoinCpuTime() - begin;
	writeSolutionInfoDetEq(osiStoch, name, duration);
	osiStoch->writeLp("DeterministicFleetAssignment");
	//delete smiModel;
}

void writeSolutionInfo(OsiStochasticParallelNestedBendersSolverInterface &benders, const char *name) {
	string filename = name;
	filename = filename.append(".txt");
	ofstream ofs;
	ofs.open(filename.c_str(), std::ios::app);
	ofs << "Obj. Value: " << benders.getObjValue() << endl;
	//ofs << "Duration (secs): " << benders.getSolutionTime() << endl;
	//ofs << "Iterations: " << benders.getIterationCount() << endl;
	ofs << "-------------------------" << endl;
	ofs.close();
}

void solveBendersFromSMPS(const char *name) {


	//smiModel->setOsiSolverHandle(osi_cpx);
	//smiModel->readSmps(name,SmiCoreCombineReplace::Instance());
	SmiScnModel* smiModel = new SmiScnModel();
	OsiCpxSolverInterface c1;
	smiModel->setOsiSolverHandle(c1);
	smiModel->readSmps(name,SmiCoreCombineReplace::Instance());

	OsiCpxSolverInterface osi_cpx;
	OsiStochasticParallelNestedBendersSolverInterface nested_benders(&osi_cpx, smiModel);

	parallel_benders::Parameter benders_parameter;
	benders_parameter.init();
	benders_parameter.parameter_.add(parallel_benders::PNB_BENDERS,true);
	benders_parameter.parameter_.add(parallel_benders::PNB_COMPUTE_PRIMAL_SOLUTIONS,parallel_benders::PNB_INT_SOLUTION_PRIMAL_ALL);
	benders_parameter.parameter_.add(parallel_benders::PNB_AGGREGATED_OPTIMALITY_CUTS,0);
	//benders_parameter.parameter_.add(parallel_benders::PNB_TOLERANCE_INTEGER, std::pow(10,-3));
	
	nested_benders.setParameters(benders_parameter);
	nested_benders.initialSolve();


}







